      "key": "legacy-stat-constructor",
      "scope": [
        "StatByCoefficientCalculationPart",
        "StatByNamedDataValueCalculationPart",
        "StatBySubPartCalculationPart"
      ],
      "facts": {
        "mStat": 0,
